static settings_t user_settings = {
    .volume = 70,
    .brightness = 80,
    .auto_remind = true,
    .remind_interval = 60
};

/* 提醒列表 */
#define MAX_REMINDERS 10
typedef struct {
    char title[64];
    char time[32];
