/* ==================== 全局变量 ==================== */
static lv_obj_t *current_screen = NULL;
static lv_obj_t *menu_panel = NULL;
static lv_obj_t *setting_panel = NULL;
static lv_obj_t *reminder_panel = NULL;

/* 当前状态 */
