/* ==================== 编码 MQTT 剩余长度 ==================== */
static int mqtt_encode_remaining_length(uint8_t *buf, int length)
{
    int pos = 0;
    do {
        uint8_t byte = length % 128;
        length /= 128;
        if (length > 0) {
            byte |= 0x80;
        }
        buf[pos++] = byte;
    } while (length > 0);
    return pos;
}

