355	/* 创建 TCP Socket */
356	static int create_tcp_socket(const char *host, uint16_t port)
357	{
358	    int sockfd;
359	    struct sockaddr_in server_addr;
360	
361	    /* 创建 socket */
362	    sockfd = socket(AF_INET, SOCK_STREAM, 0);
363	    if (sockfd < 0) {
364	        perror("socket");
365	        return -1;
366	    }
367	
368	    /* 设置服务器地址 */
369	    memset(&server_addr, 0, sizeof(server_addr));
370	    server_addr.sin_family = AF_INET;
371	    server_addr.sin_port = htons(port);
372	
373	    /* 解析主机名或 IP */
374	    struct hostent *he = gethostbyname(host);
375	    if (he) {
376	        memcpy(&server_addr.sin_addr, he->h_addr_list[0], he->h_length);
377	    } else {
378	        server_addr.sin_addr.s_addr = inet_addr(host);
379	    }
380	
381	    /* 连接服务器 */
382	    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
383	        perror("connect");
384	        close(sockfd);
385	        return -1;
386	    }
387	
388	    return sockfd;
389	}
