391	/* 发送 MQTT CONNECT 包 */
392	static int mqtt_send_connect(void)
393	{
394	    uint8_t packet[512];
395	    int pos = 0;
396	
397	    /* 固定头: CONNECT = 0x10 */
398	    packet[pos++] = 0x10;
399	
400	    /* 可变头 */
401	    uint8_t variable_header[] = {
402	        0x00, 0x04, 'M', 'Q', 'T', 'T',  // 协议名
403	        0x04,  // 协议级别 (MQTT 3.1.1)
404	        0xC2,  // 连接标志（用户名+密码+遗嘱+清理会话）
405	        0x00, 0x3C,  // 保持连接时间 60 秒
406	    };
407	
408	    /* 构建载荷 */
409	    uint8_t payload[256];
410	    int payload_pos = 0;
411	
412	    /* 客户端 ID */
413	    int client_id_len = strlen(mqtt_config.client_id);
414	    payload[payload_pos++] = (client_id_len >> 8) & 0xFF;
415	    payload[payload_pos++] = client_id_len & 0xFF;
416	    memcpy(&payload[payload_pos], mqtt_config.client_id, client_id_len);
417	    payload_pos += client_id_len;
418	
419	    /* 遗嘱主题 */
420	    char will_topic[128];
421	    snprintf(will_topic, sizeof(will_topic), "zhi_ai/%s/status", mqtt_config.client_id);
422	    int will_topic_len = strlen(will_topic);
423	    payload[payload_pos++] = (will_topic_len >> 8) & 0xFF;
424	    payload[payload_pos++] = will_topic_len & 0xFF;
425	    memcpy(&payload[payload_pos], will_topic, will_topic_len);
426	    payload_pos += will_topic_len;
427	
428	    /* 遗嘱消息 */
429	    payload[payload_pos++] = 0x00;
430	    payload[payload_pos++] = 0x03;
431	    payload[payload_pos++] = 'O';
432	    payload[payload_pos++] = 'F';
433	    payload[payload_pos++] = 'F';
434	
435	    /* 用户名 */
436	    if (mqtt_config.username[0]) {
437	        int username_len = strlen(mqtt_config.username);
438	        payload[payload_pos++] = (username_len >> 8) & 0xFF;
439	        payload[payload_pos++] = username_len & 0xFF;
440	        memcpy(&payload[payload_pos], mqtt_config.username, username_len);
441	        payload_pos += username_len;
442	    }
443	
444	    /* 密码 */
445	    if (mqtt_config.password[0]) {
446	        int password_len = strlen(mqtt_config.password);
447	        payload[payload_pos++] = (password_len >> 8) & 0xFF;
448	        payload[payload_pos++] = password_len & 0xFF;
449	        memcpy(&payload[payload_pos], mqtt_config.password, password_len);
450	        payload_pos += password_len;
451	    }
452	
453	    /* 计算剩余长度并编码 */
454	    int remaining = sizeof(variable_header) + payload_pos;
455	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
456	
457	    /* 复制可变头和载荷 */
458	    memcpy(&packet[pos], variable_header, sizeof(variable_header));
459	    pos += sizeof(variable_header);
460	    memcpy(&packet[pos], payload, payload_pos);
461	    pos += payload_pos;
462	
463	    /* 发送 */
464	    return send(mqtt_socket, packet, pos, 0);
465	}
