467	/* 发送 MQTT SUBSCRIBE 包 */
468	static int mqtt_send_subscribe(const char *topic, int qos)
469	{
470	    uint8_t packet[256];
471	    int pos = 0;
472	
473	    /* 固定头: SUBSCRIBE = 0x82 */
474	    packet[pos++] = 0x82;
475	
476	    /* 剩余长度 = 2(包ID) + 2(topic长度) + topic_len + 1(QoS) */
477	    int topic_len = strlen(topic);
478	    int remaining = 2 + 2 + topic_len + 1;
479	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
480	
481	    /* 包 ID */
482	    static uint16_t subscribe_id = 0;
483	    subscribe_id++;
484	    packet[pos++] = (subscribe_id >> 8) & 0xFF;
485	    packet[pos++] = subscribe_id & 0xFF;
486	
487	    /* 主题过滤器 */
488	    packet[pos++] = (topic_len >> 8) & 0xFF;
489	    packet[pos++] = topic_len & 0xFF;
490	    memcpy(&packet[pos], topic, topic_len);
491	    pos += topic_len;
492	
493	    /* QoS */
494	    packet[pos++] = qos;
495	
496	    return send(mqtt_socket, packet, pos, 0);
497	}
498	
499	/* 发送 MQTT PUBLISH 包 */
500	static int mqtt_send_publish(const char *topic, const char *payload, int qos, bool retain)
501	{
502	    uint8_t packet[1024];
503	    int pos = 0;
504	
505	    /* 固定头 */
506	    uint8_t type = 0x30;  // PUBLISH
507	    if (qos == 1) type |= 0x02;
508	    if (qos == 2) type |= 0x04;
509	    if (retain) type |= 0x01;
510	    packet[pos++] = type;
511	
512	    /* 剩余长度 = 2 + topic_len + payload_len [+ 2(包ID)] */
513	    int topic_len = strlen(topic);
514	    int payload_len = strlen(payload);
515	    int remaining = 2 + topic_len + payload_len;
516	    if (qos > 0) remaining += 2;
517	    pos += mqtt_encode_remaining_length(&packet[pos], remaining);
518	
519	    /* 主题名 */
520	    packet[pos++] = (topic_len >> 8) & 0xFF;
521	    packet[pos++] = topic_len & 0xFF;
522	    memcpy(&packet[pos], topic, topic_len);
523	    pos += topic_len;
524	
525	    /* 包 ID（QoS 1 或 2 时） */
526	    if (qos > 0) {
527	        static uint16_t packet_id = 0;
528	        packet_id++;
529	        packet[pos++] = (packet_id >> 8) & 0xFF;
530	        packet[pos++] = packet_id & 0xFF;
531	    }
532	
533	    /* 载荷 */
534	    memcpy(&packet[pos], payload, payload_len);
535	    pos += payload_len;
536	
537	    return send(mqtt_socket, packet, pos, 0);
538	}
