554	/* 解析 MQTT 数据包 */
555	static int mqtt_parse_packet(void)
556	{
557	    uint8_t buffer[1024];
558	    int len = recv(mqtt_socket, buffer, sizeof(buffer), 0);
559	    if (len <= 0) {
560	        return -1;
561	    }
562	
563	    uint8_t type = (buffer[0] >> 4) & 0x0F;
564	
565	    switch (type) {
566	        case 0x0D:  // PINGRESP
567	            printf("Received PINGRESP\n");
568	            break;
569	
570	        case 0x03:  // PUBLISH
571	            /* 解析主题和载荷 */
572	            {
573	                int pos = 1;
574	
575	                /* 跳过剩余长度编码 */
576	                int remaining = 0;
577	                int multiplier = 1;
578	                do {
579	                    remaining += (buffer[pos] & 0x7F) * multiplier;
580	                    multiplier *= 128;
581	                    pos++;
582	                } while (buffer[pos - 1] & 0x80);
583	
584	                /* 解析主题 */
585	                int topic_len = (buffer[pos] << 8) | buffer[pos + 1];
586	                pos += 2;
587	
588	                char topic[128];
589	                int copy_len = topic_len < (int)(sizeof(topic) - 1) ? topic_len : (int)(sizeof(topic) - 1);
590	                memcpy(topic, &buffer[pos], copy_len);
591	                topic[copy_len] = '\0';
592	                pos += topic_len;
593	
594	                /* 解析载荷 */
595	                char payload[1024];
596	                int payload_len = len - pos;
597	                if (payload_len > (int)(sizeof(payload) - 1)) {
598	                    payload_len = (int)(sizeof(payload) - 1);
599	                }
600	                memcpy(payload, &buffer[pos], payload_len);
601	                payload[payload_len] = '\0';
602	
603	                printf("Received: topic=%s, payload=%s\n", topic, payload);
604	
605	                /* 调用回调 */
606	                if (mqtt_callback) {
607	                    mqtt_callback(topic, payload);
608	                }
609	            }
610	            break;
611	
612	        default:
613	            printf("Unknown packet type: %d\n", type);
614	            break;
615	    }
616	
617	    return 0;
618	}
