/* 发送 HTTP POST 请求 */
static int http_post(const char *url, const char *body)
{
    char host[128] = {0};
    char path[256] = {0};
    int port = 443;

    /* 解析 URL */
    if (sscanf(url, "https://%127[^/]/%255s", host, path) != 2) {
        if (sscanf(url, "http://%127[^/]/%255s", host, path) != 2) {
