/**
 * ai_bridge.h - AI 模块与 UI 模块的桥接
 * 连接 robot_ui 和 hello_app 的 AI 模块
 */

#ifndef AI_BRIDGE_H
#define AI_BRIDGE_H

#include <stdint.h>
#include <stdbool.h>

/* AI 模块状态 */
typedef enum {
    AI_BRIDGE_IDLE,         // 空闲
    AI_BRIDGE_LISTENING,    // 监听中
    AI_BRIDGE_THINKING,     // AI 思考中
    AI_BRIDGE_SPEAKING,     // 说话中
    AI_BRIDGE_ALARM,        // 报警中
    AI_BRIDGE_MAX
} ai_bridge_state_t;

/* AI 回复回调 */
typedef void (*ai_bridge_reply_cb)(const char *reply);

/* 异常检测回调 */
typedef void (*ai_bridge_alarm_cb)(const char *type, const char *details);

/**
 * 初始化 AI 桥接模块
 * @return 0 成功, -1 失败
 */
int ai_bridge_init(void);

/**
 * 开始语音监听
 * @return 0 成功, -1 失败
 */
int ai_bridge_start_listening(void);

/**
 * 停止语音监听
 * @return 0 成功, -1 失败
 */
int ai_bridge_stop_listening(void);

/**
 * 发送文本到 AI 并获取回复
 * @param text  输入文本
 * @return 0 成功, -1 失败
 */
int ai_bridge_send_text(const char *text);

/**
 * 获取 AI 桥接状态
 * @return 当前状态
 */
ai_bridge_state_t ai_bridge_get_state(void);

/**
 * 注册 AI 回复回调
 * @param callback  回调函数
 */
void ai_bridge_set_reply_callback(ai_bridge_reply_cb callback);

/**
 * 注册异常检测回调
 * @param callback  回调函数
 */
void ai_bridge_set_alarm_callback(ai_bridge_alarm_cb callback);

/**
 * AI 桥接主循环处理
 * 需要在主循环中定期调用
 */
void ai_bridge_run(void);

/**
 * 检查 AI 模块是否就绪
 * @return true 就绪, false 未就绪
 */
bool ai_bridge_is_ready(void);

#endif /* AI_BRIDGE_H */

